1	// Python value semantics that YAML round-tripping depends on.
2	//
3	// Mapping of Python types onto JS:
4	//   None            -> null
5	//   bool            -> true / false
6	//   int            -> BigInt          (arbitrary precision, distinct from float)
7	//   float           -> number          (1 and 1.0 must dump differently)
8	//   str             -> string
9	//   bytes           -> PyBytes
10	//   list            -> Array
11	//   tuple           -> PyTuple
12	//   set             -> PySet
13	//   dict            -> PyDict         (insertion ordered, Python key equality)
14	//   datetime.date     -> PyDate
15	//   datetime.datetime -> PyDateTime
16	
17	import { PyTypeError } from './errors.mjs';
18	
19	export class PyBytes {
20	  constructor(bytes) {
21	    this.bytes = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
22	  }
23	}
24	
25	export class PyTuple {
26	  constructor(items) {
27	    this.items = items;
28	  }
29	}
