31	/** Python's datetime.date. */
32	export class PyDate {
33	  constructor(year, month, day) {
34	    this.year = year;
35	    this.month = month;
36	    this.day = day;
37	  }
38	
39	  /** date.isoformat() */
40	  isoformat() {
41	    return `${pad(this.year, 4)}-${pad(this.month, 2)}-${pad(this.day, 2)}`;
42	  }
43	}
