311	/** Compare two strings by code point, the way Python compares str. */
312	function codePointLess(a, b) {
313	  const as = [...a];
314	  const bs = [...b];
315	  const n = Math.min(as.length, bs.length);
316	  for (let i = 0; i < n; i++) {
317	    const x = as[i].codePointAt(0);
318	    const y = bs[i].codePointAt(0);
319	    if (x !== y) return x < y;
320	  }
321	  return as.length < bs.length;
322	}
323	
324	function bytesLess(a, b) {
325	  const n = Math.min(a.length, b.length);
326	  for (let i = 0; i < n; i++) {
327	    if (a[i] !== b[i]) return a[i] < b[i];
328	  }
329	  return a.length < b.length;
330	}
331	
332	function compareDateTime(a, b) {
333	  // Aware and naive datetimes cannot be ordered against each other.
334	  if ((a.tzOffsetMinutes === null) !== (b.tzOffsetMinutes === null)) {
335	    throw new PyTypeError("can't compare offset-naive and offset-aware datetimes");
336	  }
337	  const ka = dateTimeSortKey(a);
338	  const kb = dateTimeSortKey(b);
339	  for (let i = 0; i < ka.length; i++) {
340	    if (ka[i] !== kb[i]) return ka[i] < kb[i] ? -1 : 1;
341	  }
342	  return 0;
343	}
344	
345	function dateTimeSortKey(d) {
346	  const offset = d.tzOffsetMinutes === null ? 0 : d.tzOffsetMinutes;
347	  const days = daysFromCivil(d.year, d.month, d.day);
348	  const minutes = days * 1440 + d.hour * 60 + d.minute - offset;
349	  return [minutes, d.second, d.microsecond];
350	}
351	
352	function daysFromCivil(y, m, d) {
353	  const yy = m <= 2 ? y - 1 : y;
354	  const era = Math.floor(yy / 400);
355	  const yoe = yy - era * 400;
356	  const mp = (m + 9) % 12;
357	  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
358	  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
359	  return era * 146097 + doe - 719468;
360	}
361	
362	/** Python's `a == b` for the value types we can produce. */
363	export function pyEquals(a, b) {
364	  const ca = orderClass(a);
365	  const cb = orderClass(b);
366	  if (a === null || b === null) return a === b;
367	  if (ca !== cb || ca === UNORDERABLE) {
368	    // Different families compare unequal rather than raising.
369	    if (ca === UNORDERABLE || cb === UNORDERABLE) {
370	      try {
371	        return pyKey(a) === pyKey(b);
372	      } catch {
373	        return a === b;
374	      }
375	    }
376	    return false;
377	  }
378	  try {
379	    return !pyLessThan(a, b) && !pyLessThan(b, a);
380	  } catch {
381	    return false;
382	  }
383	}
