429	// base64, matching Python's base64 module
430	// ---------------------------------------------------------------------------
431	
432	const B64_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
433	
434	/** base64.encodebytes(): wrapped at 76 characters, trailing newline. */
435	export function encodeBase64Wrapped(bytes) {
436	  let raw = '';
437	  for (let i = 0; i < bytes.length; i += 3) {
438	    const b0 = bytes[i];
439	    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
440	    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
441	    raw += B64_ALPHABET[b0 >> 2];
442	    raw += B64_ALPHABET[((b0 & 0x03) << 4) | (b1 >> 4)];
443	    raw += i + 1 < bytes.length ? B64_ALPHABET[((b1 & 0x0f) << 2) | (b2 >> 6)] : '=';
444	    raw += i + 2 < bytes.length ? B64_ALPHABET[b2 & 0x3f] : '=';
445	  }
446	  let out = '';
447	  for (let i = 0; i < raw.length; i += 76) out += raw.slice(i, i + 76) + '\n';
448	  if (raw.length === 0) out = '';
449	  return out;
450	}
