452	/**
453	 * binascii.a2b_base64(): skip characters outside the alphabet, stop at padding,
454	 * and raise on a truncated final group.
455	 */
456	export function decodeBase64(text) {
457	  const values = [];
458	  for (const ch of text) {
459	    if (ch === '=') break;
460	    const idx = B64_ALPHABET.indexOf(ch);
461	    if (idx >= 0) values.push(idx);
462	  }
463	  if (values.length % 4 === 1) {
464	    const err = new Error('Invalid base64-encoded string: number of data characters (' +
465	      values.length + ') cannot be 1 more than a multiple of 4');
466	    err.qualifiedName = 'binascii.Error';
467	    throw err;
468	  }
469	  const out = [];
470	  for (let i = 0; i + 1 < values.length; i += 4) {
471	    const n = values.length - i;
472	    out.push(((values[i] << 2) | (values[i + 1] >> 4)) & 0xff);
473	    if (n >= 3) out.push(((values[i + 1] << 4) | (values[i + 2] >> 2)) & 0xff);
474	    if (n >= 4) out.push(((values[i + 2] << 6) | values[i + 3]) & 0xff);
475	  }
476	  return new Uint8Array(out);
477	}
